  const b0 = batches[0].json;
  const items = retry.map((u) => ({
    id: u.id, source: u.source, language_hint: u.language_hint, rating: u.rating, text: u.text,
    pii_detected_by_regex: u.pii_detected,
  }));
  const note = '\n\nThis is a retry: your previous answer for these items could not be used ('
    + [...new Set(retry.flatMap((u) => u.problems))].join('; ')
    + '). Return only the JSON object, exactly as specified.';
  retry_request_body = {
    ...b0.request_body,
    messages: [{ role: 'user', content: b0.user_template.split('__ITEMS__').join(JSON.stringify(items, null, 1)) + note }],
  };
}

return [{ json: { ok, retry, errors, retry_count: retry.length, retry_request_body } }];

// Route items: the routing policy, in one readable place. The first rule that matches wins.
//   1. moderation = reject                 -> rejected           (moderation queue, reason kept)
//   2. needs_customer_service = true       -> customer_service   (CS queue)
//   3. moderation = review (PII etc.)      -> review             (moderation queue)
//   4. no SKU, or confidence below 0.6     -> needs_human_match  (moderation queue)
//   5. otherwise                           -> approved           (webshop)
// Items that failed validation twice go to the moderation queue as "error".
// `route` says why; `queue` says where it goes (the Switch node uses `queue`).

const settings = $('Settings').first().json;
const { ok, errors } = $input.first().json;

function routeOf(r) {
  if (r.moderation === 'reject') return ['rejected', 'moderation'];
  if (r.needs_customer_service) return ['customer_service', 'customer_service'];
  if (r.moderation === 'review') return ['review', 'moderation'];
  if (!r.matched_sku || r.match_confidence < settings.min_match_confidence) return ['needs_human_match', 'moderation'];
  return ['approved', 'webshop'];
}

const out = ok.map((r) => {
  const [route, queue] = routeOf(r);
  return { json: { ...r, route, queue } };
});
for (const e of errors) out.push({ json: { ...e, route: 'error', queue: 'moderation' } });

out.sort((a, b) => a.json.id.localeCompare(b.json.id));
return out;

// Aggregate per SKU: turns approved UGC into one record per product, ready for a product page.
// Top quotes = highest quote_score from Claude, with a small bonus for items that have media.

const catalogue = $('Build Claude batches').first().json.catalogue;
const bySkuInfo = Object.fromEntries(catalogue.map((p) => [p.sku, p]));
const MEDIA_BONUS = 0.1;

const groups = {};
for (const { json: r } of $input.all()) {
  (groups[r.matched_sku] = groups[r.matched_sku] || []).push(r);
}

const products = Object.entries(groups).map(([sku, items]) => {
  const ratings = items.map((r) => r.rating).filter((v) => typeof v === 'number');
  const sentiment = { positive: 0, neutral: 0, negative: 0 };
  const topicCount = {};
  for (const r of items) {
    sentiment[r.sentiment]++;
    for (const t of r.topics) topicCount[t] = (topicCount[t] || 0) + 1;
  }
  const top_quotes = items
    .filter((r) => r.suggested_quote && r.quote_score > 0)
    .sort((a, b) => (b.quote_score + (b.media ? MEDIA_BONUS : 0)) - (a.quote_score + (a.media ? MEDIA_BONUS : 0)))
    .slice(0, 3)
    .map((r) => ({
      text: r.suggested_quote,
      lang: r.quote_language,
      source: r.source,
      author: r.author_handle,
      rating: r.rating,
      media: r.media,
      ugc_id: r.id,
    }));

  const info = bySkuInfo[sku] || {};
  return {
    json: {
      sku,
      name: info.name,
      brand: info.brand,
      category: info.category,
      url_slug: info.url_slug,
      ugc_count: items.length,
      avg_rating: ratings.length ? Math.round((ratings.reduce((a, b) => a + b, 0) / ratings.length) * 10) / 10 : null,
      rating_count: ratings.length,
      sentiment,
      top_topics: Object.entries(topicCount).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([t]) => t),
      top_quotes,
    },
  };
});

products.sort((a, b) => b.json.ugc_count - a.json.ugc_count || a.json.sku.localeCompare(b.json.sku));
return products;

// Format CS rows: the columns a customer-service agent needs.
// This queue is internal, so it keeps the full original text, including contact details.
const catalogue = $('Build Claude batches').first().json.catalogue;
const names = Object.fromEntries(catalogue.map((p) => [p.sku, p.name]));

return $input.all().map(({ json: r }) => ({
  json: {
    id: r.id,
    cs_reason: r.cs_reason,
    sku: r.matched_sku || '',
    product: names[r.matched_sku] || '',
    sentiment: r.sentiment,
    language: r.language,
    contains_pii: r.contains_pii,
    source: r.source,
    author_handle: r.author_handle,
    created_at: r.created_at,
    text: r.text,
  },
}));

// Format moderation rows: everything a human needs to decide on rejected, review,
// needs-human-match and error items, with the reason the pipeline held each one back.
return $input.all().map(({ json: r }) => ({
  json: {
    id: r.id,
    queue_reason: r.route,
    moderation: r.moderation || '',
    moderation_reason: r.moderation_reason || '',
    suggested_sku: r.matched_sku || '',
    match_confidence: r.match_confidence ?? '',
    match_reason: r.match_reason || '',
    contains_pii: r.contains_pii ?? '',
    guardrails: (r.guardrails || []).join('; '),
    problems: r.problems || '',
    source: r.source,
    author_handle: r.author_handle,
    created_at: r.created_at,
    text: r.text,
  },
}));

// Build run summary: totals per route, top products, complaint topics, items for a human,
// guardrail hits and token cost. Written to run_summary.md.

const settings = $('Settings').first().json;
const catalogue = $('Build Claude batches').first().json.catalogue;
const names = Object.fromEntries(catalogue.map((p) => [p.sku, p.name]));
const items = $input.all().map((i) => i.json);
const retryCount = $('Validate Claude output').first().json.retry_count;

// Token usage from the Claude calls (the retry node only exists in the run if it was needed)
const usageOf = (nodeName) => {
  try {
    return $(nodeName).all().map((i) => i.json.usage || {});
  } catch (e) {
    return [];
  }
};
const usage = [...usageOf('Claude: match & moderate'), ...usageOf('Claude: retry')];
const tokensIn = usage.reduce((a, u) => a + (u.input_tokens || 0), 0);
const tokensOut = usage.reduce((a, u) => a + (u.output_tokens || 0), 0);
const cost = (tokensIn * settings.price_input_per_mtok + tokensOut * settings.price_output_per_mtok) / 1e6;

const count = (pred) => items.filter(pred).length;
const routes = ['approved', 'customer_service', 'review', 'rejected', 'needs_human_match', 'error'];
const perRoute = Object.fromEntries(routes.map((r) => [r, count((i) => i.route === r)]));

// Top 5 products by positive approved UGC
const pos = {};
for (const i of items) if (i.route === 'approved' && i.sentiment === 'positive') pos[i.matched_sku] = (pos[i.matched_sku] || 0) + 1;
const topProducts = Object.entries(pos).sort((a, b) => b[1] - a[1]).slice(0, 5);

// Most common complaint topics: negative items + customer-service items
const complaintTopics = {};
for (const i of items) {
  if (i.sentiment === 'negative' || i.route === 'customer_service') {
    for (const t of i.topics || []) complaintTopics[t] = (complaintTopics[t] || 0) + 1;
  }
}
const topComplaints = Object.entries(complaintTopics).sort((a, b) => b[1] - a[1]).slice(0, 5);

const needsHuman = items.filter((i) => i.queue !== 'webshop');
const guardrailHits = items.filter((i) => (i.guardrails || []).length);
const piiRegex = count((i) => i.pii_detected_by_regex);
const piiClaudeOnly = count((i) => i.contains_pii && !i.pii_detected_by_regex);

const short = (t, n = 70) => (t.length > n ? t.slice(0, n - 1) + '…' : t);
const lines = [];
lines.push('# UGC pipeline run summary', '');
lines.push(`Run: ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC · model ${settings.model} · ${items.length} items`, '');
lines.push('## Totals per route', '', '| Route | Items |', '|---|---|');
for (const r of routes) lines.push(`| ${r} | ${perRoute[r]} |`);
lines.push('');
lines.push(`- Personal data: ${piiRegex} caught by regex, ${piiClaudeOnly} more caught only by Claude`);
lines.push(`- Items retried after a bad response: ${retryCount}`);
lines.push(`- Guardrail corrections: ${guardrailHits.length}`);
lines.push(`- Tokens: ${tokensIn.toLocaleString('en')} in / ${tokensOut.toLocaleString('en')} out (about $${cost.toFixed(3)})`, '');

lines.push('## Top 5 products by positive UGC', '');
if (!topProducts.length) lines.push('_none_');
topProducts.forEach(([sku, n], idx) => lines.push(`${idx + 1}. **${names[sku]}** (${sku}): ${n} positive`));
lines.push('');

lines.push('## Most common complaint topics', '');
if (!topComplaints.length) lines.push('_none_');
for (const [t, n] of topComplaints) lines.push(`- ${t} (${n})`);
lines.push('');

lines.push('## Needs a human', '', '| Item | Queue | Why | Text |', '|---|---|---|---|');
for (const i of needsHuman) {
  const why = i.route === 'customer_service' ? i.cs_reason
    : i.route === 'needs_human_match' ? (i.match_reason || 'no confident match')
    : i.route === 'error' ? i.problems
    : i.moderation_reason;
  lines.push(`| ${i.id} | ${i.route} | ${short(String(why || ''), 60).replace(/\|/g, '/')} | ${short(i.text).replace(/\|/g, '/')} |`);
}
lines.push('');

if (guardrailHits.length) {
  lines.push('## Guardrail corrections', '');
  for (const i of guardrailHits) lines.push(`- ${i.id}: ${i.guardrails.join('; ')}`);
  lines.push('');
}

const topSku = topProducts[0] ? names[topProducts[0][0]] : 'n/a';
return [{
  json: {
    summary_md: lines.join('\n'),
    notification: `${items.length} UGC items processed: ${perRoute.approved} approved, ${perRoute.customer_service} for customer service, ${needsHuman.length - perRoute.customer_service} need review. Top product: ${topSku}.`,
    per_route: perRoute,
    tokens_in: tokensIn,
    tokens_out: tokensOut,
  },
}];
